  // Global tensors via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{}));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{}));

  // Weight flattened as (Cout, Cin*Kh*Kw), contiguous
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, KTotal),
      make_stride(KTotal, Int<1>{}));

  // Shared memory: weights for OcPerBlock channels x all K positions
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, KTotal),
      make_stride(KTotal, Int<1>{}));

  // Load weight chunk for this block's output channels
  for (int kk = tid; kk < KTotal; kk += Threads) {
    #pragma unroll
    for (int cc = 0; cc < OcPerBlock; ++cc) {
      int oc = oc_base + cc;
      T wval = T(0);
      if (oc < Cout) {
        wval = mW(oc, kk);
      }
      sW(cc, kk) = wval;
    }
  }
  __syncthreads();

  // Precompute output pixel coordinates handled by this thread
  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  // Accumulators, initialized with bias if present
  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < OcPerBlock; ++cc) {
    int oc = oc_base + cc;
    float bval = 0.0f;
    if (B != nullptr && oc < Cout) {
      bval = (float)B[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  // Main compute loop over all (ic, kh, kw) combinations
  for (int k = 0; k < KTotal; ++k) {
    int ic  = k / KhKw;
    int rem = k - ic * KhKw;
    int kh  = rem / Kw;
    int kw  = rem - kh * Kw;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;

      int oh = oh_arr[i];
      int ow = ow_arr[i];

      int ih = oh * stride - padding + kh;
      int iw = ow * stride - padding + kw;

      float xval = 0.0f;
      if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        xval = (float)mX(ic, ih, iw);
      }

      if (xval != 0.0f) {
        #pragma unroll
        for (int cc = 0; cc < OcPerBlock; ++cc) {
          float wval = (float)sW(cc, k);
          acc[cc][i] += xval * wval;
        }
      }
    }
  }

  // Store results
  #pragma unroll
  for (int cc = 0; cc < OcPerBlock; ++cc) {
    int oc = oc_base + cc;
    if (oc >= Cout) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      int oh = oh_arr[i];
      int ow = ow_arr[i];
      mY(oc, oh, ow) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");

  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);

  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1 assumed)");
  int64_t Kh   = w.size(2);
  int64_t Kw   = w.size(3);

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - Kh) / stride + 1;
  int64_t Wout = (Win + 2 * padding - Kw) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads    = 256;
  constexpr int PVec       = 4;
  constexpr int OcPerBlock = 32;

  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );

  int KTotal = (int)(Cin * Kh * Kw);
  size_t smem_bytes = (size_t)OcPerBlock * (size_t)KTotal * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_cute_kernel<float, Threads, PVec, OcPerBlock><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)Kh, (int)Kw,
      (int)stride, (int)padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
